def intersection(self, other, sort=False):
    self._validate_sort_keyword(sort)
    self._assert_can_do_setop(other)

    if self.equals(other):
        return self._get_reconciled_name_object(other)

    if len(self) == 0:
        return self.copy()
    if len(other) == 0:
        result = other.copy()
        if isinstance(result, type(self)):
            result._set_freq(self.freq)
        return result

    if not isinstance(other, type(self)):
        result = Index.intersection(self, other, sort=sort)
        if isinstance(result, type(self)):
            if result.freq is None:
                result._set_freq(self.freq)
        return result

    elif (
        other.freq is None
        or self.freq is None
        or other.freq != self.freq
        or not other.freq.is_anchored()
        or (not self.is_monotonic or not other.is_monotonic)
    ):
        result = Index.intersection(self, other, sort=sort)
        # Invalidate the freq of `result`, which may not be correct at this point.
        result._set_freq(None)
        result = self._shallow_copy(result._data, name=result.name)
        result._set_freq(self.freq)
        return result

    # to make our life easier, "sort" the two ranges
    if self[0] <= other[0]:
        left, right = self, other
    else:
        left, right = other, self

    # after sorting, the intersection always starts with the right index
    # and ends with the index of which the last elements is smallest
    end = min(left[-1], right[-1])
    start = right[0]

    if end < start:
        return type(self)(data=[])
    else:
        lslice = slice(*left.slice_locs(start, end))
        left_chunk = left.values[lslice]
        result = self._shallow_copy(left_chunk)
        result._set_freq(self.freq)
        return result
